import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"53、【渐】 艮下巽上","description":"周易口诀义 - 53、【渐】 艮下巽上","frontmatter":{"title":"53、【渐】 艮下巽上","description":"周易口诀义 - 53、【渐】 艮下巽上"},"headers":[],"relativePath":"zh/classics/koujueyi/055.md","filePath":"zh/classics/koujueyi/055.md"}'),r={name:"zh/classics/koujueyi/055.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_53、【渐】-艮下巽上" tabindex="-1">53、【渐】 艮下巽上 <a class="header-anchor" href="#_53、【渐】-艮下巽上" aria-label="Permalink to “53、【渐】 艮下巽上”">​</a></h1><p>彖曰：渐之进也，「女归吉」也。进得位，往有功也；进以正，可以正邦也。其位刚得中也；止而巽，动不穷也。</p><p>象曰：山上有木，渐，君子以居贤德善俗。</p><p>初六，鸿渐于干，小子厉，有言无咎。</p><p>象曰：小子之厉，义无咎也。</p><p>六二，鸿渐于磐，饮食衎衎，吉。</p><p>象曰：「饮食衎衎」，不素饱也。</p><p>九三，鸿渐于陆，夫征不复，妇孕不育，凶。利御寇。</p><p>象曰：「夫征不复」，离群丑也；「妇孕不复」，失其道也。「利用御寇」，顺相保也。</p><p>六四，鸿渐于木，或得其桷，无咎。</p><p>象曰：「或得其桷」，顺以巽也。</p><p>九五，鸿渐于陵，妇三岁不孕，终莫之胜，吉。</p><p>象曰：「终莫之胜吉」，得所愿也。</p><p>上九，鸿渐于陆，其羽可用为仪，吉。</p><p>象曰：「其羽可用为仪吉」，不可乱也。</p><p>解读</p><p>渐女归吉利贞者，渐者徐进之名，归嫁也。女子生有外成之义，以夫为家，故嫁为归也。女人之嫁，备礼乃行，吉斯善矣，故曰「女归吉」也。渐进礼，全嫁娶之正，故曰「利贞」也。象曰：「山上有木，渐」者，山上生木，渐渐进长，因山而高，非是忽然而起，故曰「渐之进」也。君子以居贤德善俗者，君子求人，须求贤德，使其居位，发施教令，善诱风俗也。侯果云：「贤者，德成之名，德是资贤之实也。」</p><p>「初六，鸿渐于干，小子厉，有言，无咎」者，鸿是水鸟，以况从下至高渐进之义；干，水涯也。鸿之进至于水涯，故曰「鸿渐于干」也。进未得位，必被凌辱，乃困于小子，危于谤言，故曰「小子厉，有言」也。虽困于小人之言，而但怀道德，安能损于君子之道？故曰「无咎」也。干亦喻水上，非安之所，更以无应也。</p><p>「六二，鸿渐于磐，饮食衎衎，吉」者，磐者，山中磐石也。以柔处中，进而得位，犹鸿鸟栖于磐石，得可安之地，故曰「鸿渐于磐」。既得可安之地，居中有应，吉福至焉，故饮食丰饱，不素饱而已，故曰「衎衎吉」也。「衎衎」是喜乐之貌也。</p><p>「九三，鸿渐于陆，夫征不复，妇孕不育，凶。利用御寇」者，陆是山顶之高处也。九三处下卦之上，如山之顶，如鸿升进至于山顶，故曰「鸿渐于陆」也。三之于二，同处一体，其犹夫妇一体之义。今九三务进，不肯却回，即是夫之征进，不肯反家，故曰「夫征不复」也。九三前进，与四相得，贪务邪偶，即妇亦不能守贞，非夫而孕，故不能育，故曰「妇孕不育」也。见利忘义，贪进忘旧，凶之道矣。与四相得，邪偶相与，恐人为难，以为间阻，故利用防御寇害，顺相保也。</p><p>六四，鸿渐于木，或得其桷，无咎者，桷，榱桷也。以柔得位，如鸿栖于平直之枝，堪榱桷之用，是可栖息之处，故曰「鸿渐于木，或得其桷」。与三相得，心无忧虑，虽乘刚相合，固无咎也。</p><p>九五，鸿渐于陵，妇三岁不孕，终莫之胜，吉。陆绩云：陆、陵俱是高处，然陵卑于陆也。九五进处尊位，如鸿进高以止于陵，故曰「鸿渐于陵」也。正应在二，隔于三、四，不得与应相交，是两情勤慕，阻隔不通，故曰「三岁不孕」也。二与五各怀中正，九五是君，三四是臣，以臣欺君，势不可胜。三岁以来，道成事济，久塞其路，不得胜于君。五、二各得其愿，故曰「终莫之胜，吉」也。</p><p>上九：鸿渐于陆，其羽可用为仪，吉者，三之于上，皆处山顶，并称「陆」也。然上九最居卦上，是能为超胜，进处高洁，不累名位。德高之人，无物屈心，不乱其志，故其羽翼清虚，可为世之仪表，峨峨清奇，可贵可则，故曰「其羽可用为仪，吉」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
